1	// 已提交命令的键值应用：把日志命令解释为 set/delete/incr 键值操作，在本次调用内
2	// 从空键值表开始，随提交位置推进按日志索引顺序应用。本文件只做纯逻辑处理。
3	package mevwatch
4	
5	import (
6		"strconv"
7		"strings"
8		"unicode"
9	)
10	
11	// 键值命令格式错误的原因（稳定标识符，帮助文档中有说明）。
12	const (
13		ApplyReasonUnknownCommand   = `invalid command: expected "set <key>=<value>" or "delete <key>"`
14		ApplyReasonEmptyKey         = "invalid command: key is empty"
15		ApplyReasonKeyHasWhitespace = "invalid command: key contains whitespace"
16		ApplyReasonKeyHasEquals     = "invalid command: key contains '='"
17		ApplyReasonSetMissingEquals = "invalid command: set requires '=' between key and value"
18		// incr 特有的三类失败：增量本身非法、当前值不是整数、相加溢出。
19		ApplyReasonIncrMissingEquals = "invalid command: incr requires '=' between key and delta"
20		ApplyReasonIncrBadDelta      = "invalid command: incr delta is not a signed 64-bit decimal integer"
21		ApplyReasonIncrBadCurrent    = "invalid command: current value is not a signed 64-bit decimal integer"
22		ApplyReasonIncrOverflow      = "invalid command: incr result exceeds signed 64-bit integer range"
23	)
24	
25	// ApplyError 描述已提交命令中第一个格式错误：出错条目的日志索引与具体原因。
26	type ApplyError struct {
27		Index  int    `json:"index"`
28		Reason string `json:"reason"`
29	}
30	
31	// kvOperation 是一条解析成功的键值命令。
32	type kvOperation struct {
33		isDelete bool
34		isIncr   bool
35		key      string
36		value    string // 仅 set 使用；按原文保留，允许为空
37		delta    int64  // 仅 incr 使用；解析时已校验为有符号 64 位整数
38	}
39	
40	// parseKVCommand 把一条命令解释为键值操作，失败时返回具体原因。
41	// 命令区分大小写，命令名后必须恰好有一个普通空格；键不能为空、不能含空白
42	// 或等号；set 以键后的第一个等号分隔值，值按原文保留（可为空、含空格、
43	// 中文及额外等号）；incr 以同样方式分隔增量，增量必须是有符号 64 位十进制
44	// 整数（允许负号与前导零，其余形式一律非法）。命令两端不做任何空白裁剪。
45	func parseKVCommand(command string) (kvOperation, string) {
46		if rest, ok := strings.CutPrefix(command, "set "); ok {
47			eq := strings.IndexByte(rest, '=')
48			if eq < 0 {
49				return kvOperation{}, ApplyReasonSetMissingEquals
50			}
51			key, value := rest[:eq], rest[eq+1:]
52			if reason := validateKVKey(key); reason != "" {
53				return kvOperation{}, reason
54			}
55			return kvOperation{key: key, value: value}, ""
56		}
57		if rest, ok := strings.CutPrefix(command, "delete "); ok {
58			if reason := validateKVKey(rest); reason != "" {
59				return kvOperation{}, reason
60			}
61			return kvOperation{isDelete: true, key: rest}, ""
62		}
63		if rest, ok := strings.CutPrefix(command, "incr "); ok {
64			eq := strings.IndexByte(rest, '=')
65			if eq < 0 {
66				return kvOperation{}, ApplyReasonIncrMissingEquals
67			}
68			key, deltaText := rest[:eq], rest[eq+1:]
69			if reason := validateKVKey(key); reason != "" {
70				return kvOperation{}, reason
71			}
72			delta, ok := parseKVInt(deltaText)
73			if !ok {
74				return kvOperation{}, ApplyReasonIncrBadDelta
75			}
76			return kvOperation{isIncr: true, key: key, delta: delta}, ""
77		}
78		return kvOperation{}, ApplyReasonUnknownCommand
79	}
80	
81	// validateKVKey 校验键：不能为空、不能含空白或等号。
82	func validateKVKey(key string) string {
83		if key == "" {
84			return ApplyReasonEmptyKey
85		}
86		for _, r := range key {
87			if unicode.IsSpace(r) {
88				return ApplyReasonKeyHasWhitespace
89			}
90			if r == '=' {
91				return ApplyReasonKeyHasEquals
92			}
93		}
94		return ""
95	}
96	
97	// parseKVInt 把字符串按有符号 64 位十进制整数解析：允许负号与前导零，
98	// 不接受正号、空白、小数、指数形式或非 ASCII 数字，空字符串也不是整数；
99	// 超出 int64 范围同样失败。先逐字节校验形状，再交给 strconv 判定范围。
100	func parseKVInt(s string) (int64, bool) {
101		digits := s
102		if strings.HasPrefix(digits, "-") {
103			digits = digits[1:]
104		}
105		if digits == "" {
106			return 0, false
107		}
108		for i := 0; i < len(digits); i++ {
109			if digits[i] < '0' || digits[i] > '9' {
110				return 0, false
111			}
112		}
113		value, err := strconv.ParseInt(s, 10, 64)
114		if err != nil {
115			return 0, false
116		}
117		return value, true
118	}
119	
120	// addKVInt 计算两个有符号 64 位整数之和，结果超出 int64 范围时 ok 为 false。
121	func addKVInt(a, b int64) (sum int64, ok bool) {
122		sum = a + b
123		// Go 的有符号溢出按二进制补码回绕：b 为正而和反而变小，或 b 为负而和
124		// 反而变大，即越界。
125		if (b > 0 && sum < a) || (b < 0 && sum > a) {
126			return 0, false
127		}
128		return sum, true
129	}
130	
131	// kvApplier 在本次调用内从空键值表开始，按日志索引顺序应用已提交命令。
132	// 一旦遇到格式错误，应用状态停住：已应用索引不再前进，错误保留到调用结束。
133	type kvApplier struct {
134		kv           map[string]string
135		appliedIndex int         // 已应用的最高日志索引，0 表示尚未应用任何条目
136		err          *ApplyError // 非空后应用状态停住
137	}
138	
139	func newKVApplier() *kvApplier {
140		return &kvApplier{kv: map[string]string{}}
141	}
142	
143	// applyUpTo 应用 (appliedIndex, committedIndex] 区间内尚未应用的已提交条目。
144	// 只前进不后退：空条目心跳、重复复制、提交位置不变时不会重复应用（incr 也
145	// 不会因此重复累加）；已出错时不再应用任何条目。未提交的条目不在此触及，
146	// 其格式错误不会提前暴露。
147	func (a *kvApplier) applyUpTo(log []LogEntry, committedIndex int) {
148		if a.err != nil {
149			return
150		}
151		for a.appliedIndex < committedIndex {
152			next := a.appliedIndex + 1
153			op, reason := parseKVCommand(log[next-1].Command)
154			if reason != "" {
155				// 保留此前已成功应用的结果，已应用索引停在出错位置的前一条。
156				a.err = &ApplyError{Index: next, Reason: reason}
157				return
158			}
159			switch {
160			case op.isDelete:
161				delete(a.kv, op.key) // 删除不存在的键同样算成功，该位置照常标记已应用
162			case op.isIncr:
163				newValue, reason := a.incrValue(op)
164				if reason != "" {
165					// 当前值非法或相加溢出：本条命令不改变键值表，应用停在此处。
166					a.err = &ApplyError{Index: next, Reason: reason}
167					return
168				}
169				a.kv[op.key] = newValue
170			default:
171				a.kv[op.key] = op.value
172			}
173			a.appliedIndex = next
174		}
175	}
176	
177	// incrValue 计算一次增量后的新值：键不存在时当前值按 0 处理（并因此创建
178	// 该键）；当前值必须是有符号 64 位十进制整数，相加结果也不得超出该范围。
179	// 成功时返回不带前导零的规范十进制形式（零统一为 "0"），增量为 0 同样
180	// 写回规范形式；失败时返回具体原因，键值表保持不变。
181	func (a *kvApplier) incrValue(op kvOperation) (string, string) {
182		current := int64(0)
183		if existing, ok := a.kv[op.key]; ok {
184			value, valid := parseKVInt(existing)
185			if !valid {
186				return "", ApplyReasonIncrBadCurrent
187			}
188			current = value
189		}
190		sum, ok := addKVInt(current, op.delta)
191		if !ok {
192			return "", ApplyReasonIncrOverflow
193		}
194		return strconv.FormatInt(sum, 10), ""
195	}
196

