59	// 基本语义：键不存在按 0 创建；set 之后累加；delete 之后重新从 0 计；
60	// 结果为规范十进制字符串。
61	func TestKVIncrBasicSemantics(t *testing.T) {
62		out := runKV(t, InitialState{CurrentTerm: 1},
63			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 6,
64				Entries: []LogEntry{
65					entry(1, 1, "incr hits=1"),    // 键不存在：按 0 创建
66					entry(2, 1, "set count=7"),    // 先前写入决定当前值
67					entry(3, 1, "incr count=-2"),  // 7 + (-2) = 5
68					entry(4, 1, "delete count"),   // 删除后
69					entry(5, 1, "incr count=10"),  // 重新从 0 计：10
70					entry(6, 1, "incr hits=-007"), // 1 + (-7) = -6，前导零合法
71				}},
