78		}
79		kv := finalKVOf(t, out)
80		want := map[string]string{"hits": "-6", "count": "10"}
81		if !reflect.DeepEqual(kv, want) {
82			t.Fatalf("finalKV = %v, want %v", kv, want)
83		}
84	}
