305	// incr 失败后应用停住：后续请求复制与提交照常推进，但不再应用任何条目。
306	func TestKVIncrErrorStopsLaterApplication(t *testing.T) {
307		out := runKV(t, InitialState{CurrentTerm: 1},
308			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 2,
309				Entries: []LogEntry{entry(1, 1, "incr k=1"), entry(2, 1, "incr k=abc")}},
310			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 1, LeaderCommit: 3,
311				Entries: []LogEntry{entry(3, 2, "incr k=100")}},
312		)
