1	package mevwatch
2	
3	import (
4		"encoding/json"
5		"math"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	func runKV(t *testing.T, initial InitialState, requests ...AppendRequest) ReplicateOutput {
12		t.Helper()
13		out, err := ReplicateWithOptions(initial, requests, ReplicateOptions{ApplyKV: true})
14		if err != nil {
15			t.Fatalf("ReplicateWithOptions returned error: %v", err)
16		}
17		return out
18	}
19	
20	func appliedIndexOf(t *testing.T, result AppendResult) int {
21		t.Helper()
22		if result.AppliedIndex == nil {
23			t.Fatalf("appliedIndex missing in %+v", result)
24		}
25		return *result.AppliedIndex
26	}
27	
28	func finalKVOf(t *testing.T, out ReplicateOutput) map[string]string {
29		t.Helper()
30		if out.FinalAppliedIndex == nil || out.FinalKV == nil {
31			t.Fatalf("final apply fields missing in %+v", out)
32		}
33		return out.FinalKV
34	}
35	
36	func TestKVParseCommands(t *testing.T) {
37		cases := []struct {
38			command    string
39			wantOp     kvOperation
40			wantReason string
41		}{
42			{"set x=1", kvOperation{key: "x", value: "1"}, ""},
43			{"set x=", kvOperation{key: "x", value: ""}, ""},           // 空值
44			{"set k=a b c", kvOperation{key: "k", value: "a b c"}, ""}, // 值含空格
45			{"set k=a=b=c", kvOperation{key: "k", value: "a=b=c"}, ""}, // 值含额外等号
46			{"set k=你好 世界", kvOperation{key: "k", value: "你好 世界"}, ""}, // 中文值
47			{"set k=1 ", kvOperation{key: "k", value: "1 "}, ""},       // 尾部空白保留在值里
48			{"delete x", kvOperation{isDelete: true, key: "x"}, ""},
49			{"delete 键", kvOperation{isDelete: true, key: "键"}, ""},
50			{"set", kvOperation{}, ApplyReasonUnknownCommand}, // 没有空格与键
51			{"delete", kvOperation{}, ApplyReasonUnknownCommand},
52			{"set x", kvOperation{}, ApplyReasonSetMissingEquals},     // 缺等号
53			{"set =1", kvOperation{}, ApplyReasonEmptyKey},            // 空键
54			{"set  x=1", kvOperation{}, ApplyReasonKeyHasWhitespace},  // 两个空格：键以空格开头
55			{"set x y=1", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 键含空白
56			{"set\tx=1", kvOperation{}, ApplyReasonUnknownCommand},    // 制表符不是普通空格
57			{"delete x y", kvOperation{}, ApplyReasonKeyHasWhitespace},
58			{"delete x ", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 尾部空白不裁剪
59			{"delete a=b", kvOperation{}, ApplyReasonKeyHasEquals},    // 键含等号
60			{" set x=1", kvOperation{}, ApplyReasonUnknownCommand},    // 前导空白不裁剪
61			{"SET x=1", kvOperation{}, ApplyReasonUnknownCommand},     // 区分大小写
62			{"get x", kvOperation{}, ApplyReasonUnknownCommand},
63			{"", kvOperation{}, ApplyReasonUnknownCommand},
64		}
65		for _, tc := range cases {
66			op, reason := parseKVCommand(tc.command)
67			if reason != tc.wantReason {
68				t.Fatalf("parseKVCommand(%q) reason = %q, want %q", tc.command, reason, tc.wantReason)
69			}
70			if tc.wantReason == "" && op != tc.wantOp {
71				t.Fatalf("parseKVCommand(%q) = %+v, want %+v", tc.command, op, tc.wantOp)
72			}
73		}
74	}
