506			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"appliedIndex":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
507		} {
508			var out ReplicateOutput
509			if err := json.Unmarshal([]byte(data), &out); err == nil {
510				t.Fatalf("expected decode error for %s", data)
511			}
512		}
513	}
