515	// decodeMap 把 JSON 解码为通用对象，便于只按“键是否出现”断言输出形状
516	// （不能用字符串包含判断：appliedIndex 是 finalAppliedIndex 的子串）。
517	func decodeMap(t *testing.T, data []byte) map[string]any {
518		t.Helper()
519		var m map[string]any
520		if err := json.Unmarshal(data, &m); err != nil {
521			t.Fatalf("decode %s: %v", data, err)
522		}
523		return m
524	}
