526	func mustHaveKeys(t *testing.T, m map[string]any, where string, keys ...string) {
527		t.Helper()
528		for _, key := range keys {
529			if _, ok := m[key]; !ok {
530				t.Fatalf("%s: expected key %q present in %v", where, key, m)
531			}
532		}
533	}
534	
535	func mustLackKeys(t *testing.T, m map[string]any, where string, keys ...string) {
536		t.Helper()
537		for _, key := range keys {
538			if _, ok := m[key]; ok {
539				t.Fatalf("%s: expected key %q absent in %v", where, key, m)
540			}
541		}
542	}
