544	func resultMaps(t *testing.T, m map[string]any) []map[string]any {
545		t.Helper()
546		raw, ok := m["results"].([]any)
547		if !ok {
548			t.Fatalf("results is not an array in %v", m)
549		}
550		results := make([]map[string]any, len(raw))
551		for i, item := range raw {
552			results[i], ok = item.(map[string]any)
553			if !ok {
554				t.Fatalf("result %d is not an object: %v", i, item)
555			}
556		}
557		return results
558	}
