560	// TestKVRoundTripPartialPerRequestFields 覆盖逐条请求一层只出现部分应用字段
561	// 的约定：appliedIndex 与 applyError 同组，出现任意一个再次输出就要带齐；
562	// 缺索引补 0、无错误补 null；字段出现与值为空是两回事（只有 null 错误也算
563	// 记录了应用状态）；已提供的非零索引与错误中的索引、原因原样保留。
564	func TestKVRoundTripPartialPerRequestFields(t *testing.T) {
565		cases := []struct {
566			name      string
567			extra     string
568			wantIndex float64
569			wantError any // nil 表示输出必须为 null；否则为期望的错误对象
570		}{
571			{"only zero applied index", `"appliedIndex":0`, 0, nil},
572			{"only nonzero applied index", `"appliedIndex":5`, 5, nil},
573			{"only null apply error", `"applyError":null`, 0, nil},
574			{"only apply error object",
575				`"applyError":{"index":3,"reason":"boom"}`, 0,
576				map[string]any{"index": float64(3), "reason": "boom"}},
577		}
578		for _, tc := range cases {
579			t.Run(tc.name, func(t *testing.T) {
580				data := `{"accepted":true,"reason":"ok","term":2,"committedIndex":1,` + tc.extra + `}`
581				var result AppendResult
582				if err := json.Unmarshal([]byte(data), &result); err != nil {
583					t.Fatal(err)
584				}
585				reencoded, err := json.Marshal(result)
586				if err != nil {
587					t.Fatal(err)
588				}
589				m := decodeMap(t, reencoded)
590				mustHaveKeys(t, m, "per-request result", "appliedIndex", "applyError")
591				if m["appliedIndex"] != tc.wantIndex {
592					t.Fatalf("appliedIndex = %v, want %v: %v", m["appliedIndex"], tc.wantIndex, m)
593				}
594				if tc.wantError == nil {
595					if m["applyError"] != nil {
596						t.Fatalf("applyError = %v, want null: %v", m["applyError"], m)
597					}
598				} else if !reflect.DeepEqual(m["applyError"], tc.wantError) {
599					t.Fatalf("applyError = %v, want %v", m["applyError"], tc.wantError)
600				}
601				// 复制答复的既有字段不被部分应用字段干扰。
602				if m["accepted"] != true || m["reason"] != "ok" ||
603					m["term"] != float64(2) || m["committedIndex"] != float64(1) {
604					t.Fatalf("replication fields changed: %v", m)
605				}
606			})
607		}
608	}
