610	// TestKVRoundTripPartialFinalFields 覆盖最终结果一层的部分字段约定：
611	// finalAppliedIndex、finalKV、finalApplyError 同组；缺索引补 0、缺键值表补
612	// 空对象 {}、无错误补 null；只带空键值表也要保留索引与错误字段；非零索引、
613	// 键值内容、错误索引与原因原样保留。
614	func TestKVRoundTripPartialFinalFields(t *testing.T) {
615		cases := []struct {
616			name      string
617			extra     string
618			wantIndex float64
619			wantKV    any // nil 表示必须输出空对象 {}
620			wantError any // nil 表示必须输出 null
621		}{
622			{"only zero final applied index", `"finalAppliedIndex":0`, 0, map[string]any{}, nil},
623			{"only nonzero final applied index", `"finalAppliedIndex":7`, 7, map[string]any{}, nil},
624			{"only empty final kv", `"finalKV":{}`, 0, map[string]any{}, nil},
625			{"only nonempty final kv",
626				`"finalKV":{"a":"1","b":"x=y"}`, 0,
627				map[string]any{"a": "1", "b": "x=y"}, nil},
628			{"only null final apply error", `"finalApplyError":null`, 0, map[string]any{}, nil},
629			{"only final apply error object",
630				`"finalApplyError":{"index":2,"reason":"` + ApplyReasonSetMissingEquals + `"}`, 0,
631				map[string]any{},
632				map[string]any{"index": float64(2), "reason": ApplyReasonSetMissingEquals}},
633		}
634		for _, tc := range cases {
635			t.Run(tc.name, func(t *testing.T) {
636				data := `{"results":[],"finalTerm":2,"finalCommittedIndex":1,` +
637					`"finalLog":[{"index":1,"term":1,"command":"set a=1"}],` + tc.extra + `}`
638				var out ReplicateOutput
639				if err := json.Unmarshal([]byte(data), &out); err != nil {
640					t.Fatal(err)
641				}
642				reencoded, err := json.Marshal(out)
643				if err != nil {
644					t.Fatal(err)
645				}
646				m := decodeMap(t, reencoded)
647				mustHaveKeys(t, m, "final output", "finalAppliedIndex", "finalKV", "finalApplyError")
648				if m["finalAppliedIndex"] != tc.wantIndex {
649					t.Fatalf("finalAppliedIndex = %v, want %v: %v", m["finalAppliedIndex"], tc.wantIndex, m)
650				}
651				if !reflect.DeepEqual(m["finalKV"], tc.wantKV) {
652					t.Fatalf("finalKV = %v, want %v", m["finalKV"], tc.wantKV)
653				}
654				if tc.wantError == nil {
655					if m["finalApplyError"] != nil {
656						t.Fatalf("finalApplyError = %v, want null: %v", m["finalApplyError"], m)
657					}
658				} else if !reflect.DeepEqual(m["finalApplyError"], tc.wantError) {
659					t.Fatalf("finalApplyError = %v, want %v", m["finalApplyError"], tc.wantError)
660				}
661				// 任期、提交位置与日志内容保持原样。
662				if m["finalTerm"] != float64(2) || m["finalCommittedIndex"] != float64(1) {
663					t.Fatalf("final replication fields changed: %v", m)
664				}
665				log := m["finalLog"].([]any)
666				if !reflect.DeepEqual(log[0], map[string]any{"index": float64(1), "term": float64(1), "command": "set a=1"}) {
667					t.Fatalf("finalLog changed: %v", log)
668				}
669			})
670		}
671	}
