1095			Entries: []LogEntry{entry(3, 1, "set broken")}}
1096		// 请求三：任期 3、正确匹配 idx2，追加 idx3 任期 2 的合法写入并提交到 3。
1097		legal := AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
1098			Entries: []LogEntry{entry(3, 2, "set receipt=ok")}}
1099	
1100		// 只停在第一次拒绝处：应用边界完全不动，被拒命令的格式错误不可见。
1101		stopped := runKV(t, initial, badMatching)
1102		r := stopped.Results[0]
1103		if r.Accepted || r.Reason != ReasonEntryTermDecreases {
1104			t.Fatalf("bad request should be the term-bridge field error: %+v", r)
1105		}
1106		if r.Conflict != nil {
1107			t.Fatalf("field error must not be reported as a replication conflict: %+v", r.Conflict)
1108		}
