1136		if err != nil {
1137			t.Fatal(err)
1138		}
1139		if strings.Contains(string(encoded), "broken") {
1140			t.Fatalf("rejected entry command leaked into output: %s", encoded)
1141		}
1142	
1143		// 完整过程：两种字段错误之后合法请求仍按原状态继续处理。
1144		out := runKV(t, initial, badMatching, badMismatch, legal)
1145		wantResults := []struct {
1146			accepted bool
1147			reason   string
1148			term     int
1149			commit   int
1150			applied  int
1151		}{
1152			{false, ReasonEntryTermDecreases, 2, 1, 1}, // 高任期不保留，一切不动
1153			{false, ReasonEntryTermDecreases, 2, 1, 1}, // 前置任期也不一致：仍是字段错误
1154			{true, ReasonOK, 3, 3, 3},                  // 追加 idx3 并提交、应用到 3
