1170					i, got.Term, got.CommittedIndex, want.term, want.commit)
1171			}
1172			if applied := appliedIndexOf(t, got); applied != want.applied {
1173				t.Fatalf("result %d appliedIndex = %d, want %d", i, applied, want.applied)
1174			}
1175			if got.ApplyError != nil {
1176				t.Fatalf("result %d unexpected apply error: %+v", i, got.ApplyError)
1177			}
