1460		}{
1461			// 任务中的原始问题场景：只有 "ApplyError": null。
1462			{"only capitalized null apply error", `"ApplyError":null`, 0, nil},
1463			{"only uppercase apply index zero", `"APPLIEDINDEX":0`, 0, nil},
1464			{"only uppercase nonzero apply index", `"APPLIEDINDEX":5`, 5, nil},
1465			{"only mixed-case apply error object",
1466				`"aPpLyErRoR":{"index":3,"reason":"boom"}`, 0,
1467				map[string]any{"index": float64(3), "reason": "boom"}},
1468			{"capitalized index with capitalized error",
1469				`"AppliedIndex":4,"ApplyError":{"index":6,"reason":"bad"}`, 4,
1470				map[string]any{"index": float64(6), "reason": "bad"}},
1471		}
1472		for _, tc := range cases {
1473			t.Run(tc.name, func(t *testing.T) {
1474				data := `{"accepted":true,"reason":"ok","term":2,"committedIndex":1,` + tc.extra + `}`
