1477					t.Fatal(err)
1478				}
1479				reencoded, err := json.Marshal(result)
1480				if err != nil {
1481					t.Fatal(err)
1482				}
1483				m := decodeMap(t, reencoded)
1484				// 必须以标准字段名输出，原始大小写名不得残留。
1485				mustHaveKeys(t, m, "per-request result", "appliedIndex", "applyError")
