// TestKVRoundTripFailedReuseKeepsPreviousResult 复用已有结果对象再次读入时，
// 类型非法的 JSON 必须明确报错，且原有结果完整保留——即使错误藏在某条请求
// 答复内，随后输出也不能混入这次读入的任何部分内容。
// TestKVRejectedReplicationKeepsApplyBoundary 回归保障：启用 applyKV 后复制请求
// 被拒绝时的状态边界——较高任期或较大 leaderCommit 都不能把未确认的命令写进
// 键值表。场景含一个已提交前缀与未提交尾部：
//   - 初始任期 2，idx1/idx2 任期均为 2，set balance=100 已提交而 set
//     balance=200 未提交：键值表只有 balance=100，应用位置停在 1；
//   - 任期 5 的请求把 idx2 任期错称为 3 并要求提交更后位置：因前缀不匹配被拒，
//     任期升到 5，但日志、提交位置、应用位置与键值表保持原值，无应用错误；
//   - 任期 9 但条目索引不连续的请求属于字段非法：整条拒绝且连任期都不得改变，
//     不能与上一种拒绝混为同样的状态变化；
//   - 之后任期 5、正确匹配 idx2 的合法请求追加 idx3 并提交到 3：按日志次序
//     应用尚未应用的命令，balance=200、receipt=ok，提交与应用位置均为 3。
func TestKVRejectedReplicationKeepsApplyBoundary(t *testing.T) {
	initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 2, "set balance=100"),
		entry(2, 2, "set balance=200"), // 未提交尾部：任何拒绝都不能让它被应用
	}}
	wantOriginalLog := []LogEntry{
		entry(1, 2, "set balance=100"),
		entry(2, 2, "set balance=200"),
	}

	// 没有请求时：只应用初始已提交前缀，字符串值原样保留。
	start := runKV(t, initial)
	if *start.FinalAppliedIndex != 1 {
		t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"balance": "100"}) {
		t.Fatalf("initial kv = %v, want only balance=100", start.FinalKV)
	}
	if start.FinalApplyError != nil {
		t.Fatalf("unexpected initial apply error: %+v", start.FinalApplyError)
	}

	// 请求一：高任期 + 前缀任期不匹配 + 更大的 leaderCommit，其余字段全部合法。
	mismatch := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 3, LeaderCommit: 4,
		Entries: []LogEntry{entry(3, 5, "set later=x")}}
	// 请求二：任期 9，但条目索引没有从 prevLogIndex+1 开始——字段非法。
	gap := AppendRequest{Term: 9, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 5,
		Entries: []LogEntry{entry(4, 9, "set gap=y")}} // 期望索引 3
	// 请求三：任期 5、正确匹配 idx2（任期 2）的合法追加。
	legal := AppendRequest{Term: 5, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
		Entries: []LogEntry{entry(3, 5, "set receipt=ok")}}

	// 若输入停在第一次拒绝处：任期升到 5，其余一切不动，未确认命令不入表。
	stopped := runKV(t, initial, mismatch)
	r := stopped.Results[0]
	if r.Accepted || r.Reason != ReasonPrevLogMismatch {
		t.Fatalf("first request should be rejected for prefix mismatch: %+v", r)
	}
	if r.Term != 5 {
		t.Fatalf("higher term should survive rejection: term = %d, want 5", r.Term)
	}
	if r.CommittedIndex != 1 {
		t.Fatalf("commit advanced on rejection: %d, want 1", r.CommittedIndex)
	}
	if got := appliedIndexOf(t, r); got != 1 {
		t.Fatalf("applied index advanced on rejection: %d, want 1", got)
	}
	if r.ApplyError != nil {
		t.Fatalf("rejection must not produce an apply error: %+v", r.ApplyError)
	}
	if stopped.FinalTerm != 5 || stopped.FinalCommittedIndex != 1 {
		t.Fatalf("final state after stop: term=%d ci=%d, want 5/1",
			stopped.FinalTerm, stopped.FinalCommittedIndex)
	}
	if !reflect.DeepEqual(stopped.FinalLog, wantOriginalLog) {
		t.Fatalf("log changed after rejection: %+v", stopped.FinalLog)
	}
	if *stopped.FinalAppliedIndex != 1 {
		t.Fatalf("final appliedIndex = %d, want 1", *stopped.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "100"}) {
		t.Fatalf("kv changed after rejection: %v, want only balance=100", stopped.FinalKV)
	}
	if stopped.FinalApplyError != nil {
		t.Fatalf("unexpected final apply error: %+v", stopped.FinalApplyError)
	}

	// 完整过程：两种拒绝之后合法请求仍能追加并提交。
	out := runKV(t, initial, mismatch, gap, legal)
	wantResults := []struct {
		accepted bool
		reason   string
		term     int
		commit   int
		applied  int
	}{
		{false, ReasonPrevLogMismatch, 5, 1, 1}, // 任期更新保留，其余不动
		{false, ReasonEntryIndexGap, 5, 1, 1},   // 字段非法：连任期都停在 5
		{true, ReasonOK, 5, 3, 3},               // 追加 idx3，提交并应用到 3
	}
	if len(out.Results) != len(wantResults) {
		t.Fatalf("got %d results, want %d", len(out.Results), len(wantResults))
	}
	for i, want := range wantResults {
		got := out.Results[i]
		if got.Accepted != want.accepted || got.Reason != want.reason {
			t.Fatalf("result %d = accepted=%v reason=%q, want accepted=%v reason=%q",
				i, got.Accepted, got.Reason, want.accepted, want.reason)
		}
		if got.Term != want.term || got.CommittedIndex != want.commit {
			t.Fatalf("result %d state = term %d ci %d, want term %d ci %d",
				i, got.Term, got.CommittedIndex, want.term, want.commit)
		}
		if applied := appliedIndexOf(t, got); applied != want.applied {
			t.Fatalf("result %d appliedIndex = %d, want %d", i, applied, want.applied)
		}
		if got.ApplyError != nil {
			t.Fatalf("result %d unexpected apply error: %+v", i, got.ApplyError)
		}
	}

	// 最终状态：任期 5、提交 3；日志为原两条加 idx3，未提交尾部命令原样保留。
	wantLog := []LogEntry{
		entry(1, 2, "set balance=100"),
		entry(2, 2, "set balance=200"),
		entry(3, 5, "set receipt=ok"),
	}
	if out.FinalTerm != 5 || out.FinalCommittedIndex != 3 {
		t.Fatalf("final replication state = term %d ci %d, want term 5 ci 3",
			out.FinalTerm, out.FinalCommittedIndex)
	}
	if !reflect.DeepEqual(out.FinalLog, wantLog) {
		t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
	}
	if *out.FinalAppliedIndex != 3 {
		t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
	}
	// 按原日志顺序应用：idx2 把 balance 改成 200，idx3 写入 receipt。
	wantKV := map[string]string{"balance": "200", "receipt": "ok"}
	if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
		t.Fatalf("final kv = %v, want %v", out.FinalKV, wantKV)
	}
	if out.FinalApplyError != nil {
		t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
	}
}

// partialConfirmationInitial 是“部分确认不提交尾部”回归测试的初始状态：任期 2，
// 日志索引 1..4 的任期均为 2，只有 idx1（set balance=100）已提交；idx2 把
// balance 改成 200，idx3 是缺少等号的 set 命令，idx4 删除 balance——后三条都是
// 未提交尾部，idx3 的格式错误不能在提交之前暴露。
func partialConfirmationInitial() InitialState {
	return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 2, "set balance=100"),
		entry(2, 2, "set balance=200"),
		entry(3, 2, "set balance"), // 缺少 '='：提交到此处时才报告
		entry(4, 2, "delete balance"),
	}}
}

// TestKVPartialConfirmationKeepsTailUncommitted 回归保障：合法请求只确认部分日志时，
// 本地保留的更长未提交尾部不能因此被提交或应用。日志仍然存在、日志已经提交、命令
// 已经应用是三种不同的结果，必须分别从每一步的答复与最终状态中看出：
//   - 初始只提交 idx1：键值表只有 balance=100，idx3 的格式错误不出现；
//   - 请求一（任期 2、前置 idx1、只携带与本地 idx2 相同的条目、leaderCommit=4）
//     成功且答复原因为 ok：四条日志全部保留，但提交与应用只到 2，balance=200，
//     无应用错误；
//   - 请求二（前置 idx2、空条目、leaderCommit=4）同样成功：确认位置仍是 2，尾部
//     的 delete 不执行，idx3 的格式错误也不暴露；
//   - 请求三（前置 idx4、leaderCommit=4）才把提交推进到 4：idx3 的错误被报告，
//     应用停在 2，idx4 的删除不生效，balance 仍为 200；复制仍成功、日志不变；
//   - 请求四（前置 idx2、leaderCommit=1）确认位置与领导者提交位置都低于已提交
//     索引：提交、应用与已报告的错误都不得倒退。
func TestKVPartialConfirmationKeepsTailUncommitted(t *testing.T) {
	initial := partialConfirmationInitial()
	fullLog := append([]LogEntry(nil), initial.Log...)

	// 没有请求时：只应用初始已提交前缀，尾部三条不产生任何效果。
	start := runKV(t, initial)
	if *start.FinalAppliedIndex != 1 {
		t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"balance": "100"}) {
		t.Fatalf("initial kv = %v, want only balance=100", start.FinalKV)
	}
	if start.FinalApplyError != nil {
		t.Fatalf("uncommitted bad entry reported early: %+v", start.FinalApplyError)
	}

	// 请求一：只确认到 idx2，领导者却声明已提交到 4。
	partial := AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 4,
		Entries: []LogEntry{entry(2, 2, "set balance=200")}}
	// 请求二：空条目心跳，前置仍为 idx2，领导者提交位置仍为 4。
	heartbeat := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 4}
	// 请求三：前置确认到 idx4，提交位置才推进到 4。
	confirmAll := AppendRequest{Term: 2, PrevLogIndex: 4, PrevLogTerm: 2, LeaderCommit: 4}
	// 请求四：确认位置与 leaderCommit 都低于已提交索引，不得倒退。
	lowerCommit := AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 1}

	// 若输入停在请求一：答复成功，日志四条全在，提交与应用只到 2。
	stopped := runKV(t, initial, partial)
	r := stopped.Results[0]
	if !r.Accepted || r.Reason != ReasonOK {
		t.Fatalf("partial confirmation must stay a normal success: %+v", r)
	}
	if r.CommittedIndex != 2 {
		t.Fatalf("commit advanced beyond confirmed index: %d, want 2", r.CommittedIndex)
	}
	if got := appliedIndexOf(t, r); got != 2 {
		t.Fatalf("applied index = %d, want 2", got)
	}
	if r.ApplyError != nil {
		t.Fatalf("uncommitted tail error reported early: %+v", r.ApplyError)
	}
	if !reflect.DeepEqual(stopped.FinalLog, fullLog) {
		t.Fatalf("tail deleted by partial confirmation: %+v", stopped.FinalLog)
	}
	if stopped.FinalCommittedIndex != 2 || *stopped.FinalAppliedIndex != 2 {
		t.Fatalf("final state = ci %d applied %d, want 2/2",
			stopped.FinalCommittedIndex, *stopped.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "200"}) {
		t.Fatalf("kv = %v, want only balance=200 (delete must not run)", stopped.FinalKV)
	}
	if stopped.FinalApplyError != nil {
		t.Fatalf("unexpected apply error: %+v", stopped.FinalApplyError)
	}

	// 完整过程：四个请求的答复逐步区分“日志保留 / 已提交 / 已应用”。
	out := runKV(t, initial, partial, heartbeat, confirmAll, lowerCommit)
	if len(out.Results) != 4 {
		t.Fatalf("got %d results, want 4", len(out.Results))
	}
	// 四个请求全部以正常成功原因接受：不能为了阻止尾部应用而拒绝请求。
	for i, result := range out.Results {
		if !result.Accepted || result.Reason != ReasonOK {
			t.Fatalf("result %d must be a normal success, got %+v", i, result)
		}
		if result.Term != 2 {
			t.Fatalf("result %d term = %d, want 2", i, result.Term)
		}
	}
	// 请求一、二：确认位置只有 2，leaderCommit=4 不能把提交推过 2。
	for i := 0; i < 2; i++ {
		if out.Results[i].CommittedIndex != 2 {
			t.Fatalf("result %d committedIndex = %d, want 2 (tail not confirmed)",
				i, out.Results[i].CommittedIndex)
		}
		if got := appliedIndexOf(t, out.Results[i]); got != 2 {
			t.Fatalf("result %d appliedIndex = %d, want 2", i, got)
		}
		if out.Results[i].ApplyError != nil {
			t.Fatalf("result %d exposed uncommitted tail error: %+v", i, out.Results[i].ApplyError)
		}
	}
	// 请求三：提交推进到 4，idx3 的格式错误此时才报告；应用停在 2。
	third := out.Results[2]
	if third.CommittedIndex != 4 {
		t.Fatalf("result 2 committedIndex = %d, want 4", third.CommittedIndex)
	}
	if got := appliedIndexOf(t, third); got != 2 {
		t.Fatalf("result 2 appliedIndex = %d, want 2 (stuck before bad entry)", got)
	}
	if third.ApplyError == nil || third.ApplyError.Index != 3 ||
		third.ApplyError.Reason != ApplyReasonSetMissingEquals {
		t.Fatalf("result 2 applyError = %+v, want index 3 missing '='", third.ApplyError)
	}
	// 请求四：确认位置与 leaderCommit 都低于已提交索引，一切不得倒退。
	fourth := out.Results[3]
	if fourth.CommittedIndex != 4 {
		t.Fatalf("result 3 committedIndex moved backward: %d, want 4", fourth.CommittedIndex)
	}
	if got := appliedIndexOf(t, fourth); got != 2 {
		t.Fatalf("result 3 appliedIndex = %d, want 2", got)
	}
	if fourth.ApplyError == nil || fourth.ApplyError.Index != 3 {
		t.Fatalf("result 3 applyError = %+v, want index 3 retained", fourth.ApplyError)
	}

	// 最终状态：完整日志不因应用失败而改变；提交到 4、应用停在 2、balance 仍为
	// 200——idx4 的删除不能生效，idx3 的错误保留在最终输出中。
	if !reflect.DeepEqual(out.FinalLog, fullLog) {
		t.Fatalf("final log = %+v, want unchanged %+v", out.FinalLog, fullLog)
	}
	if out.FinalTerm != 2 || out.FinalCommittedIndex != 4 {
		t.Fatalf("final state = term %d ci %d, want term 2 ci 4", out.FinalTerm, out.FinalCommittedIndex)
	}
	if *out.FinalAppliedIndex != 2 {
		t.Fatalf("final appliedIndex = %d, want 2", *out.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, out), map[string]string{"balance": "200"}) {
		t.Fatalf("final kv = %v, want only balance=200 (delete must not run)", out.FinalKV)
	}
	if out.FinalApplyError == nil || out.FinalApplyError.Index != 3 ||
		out.FinalApplyError.Reason != ApplyReasonSetMissingEquals {
		t.Fatalf("final applyError = %+v, want index 3 missing '='", out.FinalApplyError)
	}
}

// termBridgeInitial 是任期衔接回归场景的初始状态：当前任期 2，索引 1、2 的任期
// 分别为 1、2（set balance=100 已提交、set balance=200 未提交）。
func termBridgeInitial() InitialState {
	return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 1, "set balance=100"),
		entry(2, 2, "set balance=200"), // 未提交尾部：任何拒绝都不能让它生效
	}}
}

// TestKVFirstEntryTermBridgeFieldErrorAppliesNothing 回归保障任期衔接字段错误与
// 键值应用交汇时的现有行为：
//   - 任期 7、前置索引 2/前置任期 2（与本地一致）、leaderCommit 再大，但携带
//     索引 3、任期 1 的条目（首条任期低于声明的前置任期），且命令本身格式错误：
//     按字段错误拒绝，原因固定为 entry terms are not non-decreasing，不是前置
//     日志不匹配，不输出 conflict；
//   - 声明的前置任期与本地不一致（本地 idx2 任期 2、声明 5）、首条任期仍低于
//     声明值时，属于同一条字段错误，不能留下较高任期更新；
//   - 拒绝后任期仍为 2，日志与提交位置原样，应用位置停在 1，键值表只有
//     balance=100：未提交的 balance=200 不能借大 leaderCommit 生效，被拒请求中
//     格式错误的命令也不产生 applyError；
//   - 随后任期 3、正确匹配索引 2 的合法请求追加索引 3、任期 2 的
//     set receipt=ok 并提交到 3：成功，balance 变 200、receipt 变 ok，提交与
//     应用位置都到 3。
func TestKVFirstEntryTermBridgeFieldErrorAppliesNothing(t *testing.T) {
	initial := termBridgeInitial()
	originalLog := append([]LogEntry(nil), initial.Log...)

	// 请求一：前置与本地一致，首条任期低于前置任期，命令还缺等号。
	badMatching := AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 9,
		Entries: []LogEntry{entry(3, 1, "set broken")}}
	// 请求二：声明的前置任期与本地不一致，首条任期 1 仍低于声明值 5。
	badMismatch := AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 5, LeaderCommit: 9,
		Entries: []LogEntry{entry(3, 1, "set broken")}}
	// 请求三：任期 3、正确匹配 idx2，追加 idx3 任期 2 的合法写入并提交到 3。
	legal := AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
		Entries: []LogEntry{entry(3, 2, "set receipt=ok")}}

	// 只停在第一次拒绝处：应用边界完全不动，被拒命令的格式错误不可见。
	stopped := runKV(t, initial, badMatching)
	r := stopped.Results[0]
	if r.Accepted || r.Reason != ReasonEntryTermDecreases {
		t.Fatalf("bad request should be the term-bridge field error: %+v", r)
	}
	if r.Conflict != nil {
		t.Fatalf("field error must not be reported as a replication conflict: %+v", r.Conflict)
	}
	if r.Term != 2 || r.CommittedIndex != 1 {
		t.Fatalf("rejection changed replication state: %+v", r)
	}
	if got := appliedIndexOf(t, r); got != 1 {
		t.Fatalf("applied index advanced on rejection: %d, want 1", got)
	}
	if r.ApplyError != nil {
		t.Fatalf("rejected malformed command must not produce an apply error: %+v", r.ApplyError)
	}
	if !reflect.DeepEqual(stopped.FinalLog, originalLog) {
		t.Fatalf("log changed after rejection: %+v", stopped.FinalLog)
	}
	if stopped.FinalTerm != 2 || stopped.FinalCommittedIndex != 1 {
		t.Fatalf("final replication state changed: term=%d ci=%d",
			stopped.FinalTerm, stopped.FinalCommittedIndex)
	}
	if *stopped.FinalAppliedIndex != 1 {
		t.Fatalf("final appliedIndex = %d, want 1", *stopped.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, stopped), map[string]string{"balance": "100"}) {
		t.Fatalf("kv = %v, want only balance=100 (uncommitted tail must not apply)", stopped.FinalKV)
	}
	if stopped.FinalApplyError != nil {
		t.Fatalf("unexpected final apply error: %+v", stopped.FinalApplyError)
	}
	// 被拒条目既未进日志，其命令也不应出现在输出中。
	encoded, err := json.Marshal(stopped)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(encoded), "broken") {
		t.Fatalf("rejected entry command leaked into output: %s", encoded)
	}

	// 完整过程：两种字段错误之后合法请求仍按原状态继续处理。
	out := runKV(t, initial, badMatching, badMismatch, legal)
	wantResults := []struct {
		accepted bool
		reason   string
		term     int
		commit   int
		applied  int
	}{
		{false, ReasonEntryTermDecreases, 2, 1, 1}, // 高任期不保留，一切不动
		{false, ReasonEntryTermDecreases, 2, 1, 1}, // 前置任期也不一致：仍是字段错误
		{true, ReasonOK, 3, 3, 3},                  // 追加 idx3 并提交、应用到 3
	}
	if len(out.Results) != len(wantResults) {
		t.Fatalf("got %d results, want %d", len(out.Results), len(wantResults))
	}
	for i, want := range wantResults {
		got := out.Results[i]
		if got.Accepted != want.accepted || got.Reason != want.reason {
			t.Fatalf("result %d = accepted=%v reason=%q, want accepted=%v reason=%q",
				i, got.Accepted, got.Reason, want.accepted, want.reason)
		}
		if got.Conflict != nil {
			t.Fatalf("result %d must not carry conflict: %+v", i, got.Conflict)
		}
		if got.Term != want.term || got.CommittedIndex != want.commit {
			t.Fatalf("result %d state = term %d ci %d, want term %d ci %d",
				i, got.Term, got.CommittedIndex, want.term, want.commit)
		}
		if applied := appliedIndexOf(t, got); applied != want.applied {
			t.Fatalf("result %d appliedIndex = %d, want %d", i, applied, want.applied)
		}
		if got.ApplyError != nil {
			t.Fatalf("result %d unexpected apply error: %+v", i, got.ApplyError)
		}
	}

	// 最终状态：任期 3、提交与应用位置均为 3；未提交尾部在合法请求确认后才按
	// 日志次序生效——balance 变 200，receipt 写入 ok。
	wantLog := []LogEntry{
		entry(1, 1, "set balance=100"),
		entry(2, 2, "set balance=200"),
		entry(3, 2, "set receipt=ok"),
	}
	if !reflect.DeepEqual(out.FinalLog, wantLog) {
		t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
	}
	if out.FinalTerm != 3 || out.FinalCommittedIndex != 3 {
		t.Fatalf("final replication state = term %d ci %d, want term 3 ci 3",
			out.FinalTerm, out.FinalCommittedIndex)
	}
	if *out.FinalAppliedIndex != 3 {
		t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
	}
	wantKV := map[string]string{"balance": "200", "receipt": "ok"}
	if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
		t.Fatalf("final kv = %v, want %v", out.FinalKV, wantKV)
	}
	if out.FinalApplyError != nil {
		t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
	}

	// 未开启 applyKV 的同一拒绝继续省略全部应用字段，拒绝原因与无 conflict
	// 的输出约定不变。
	plain, err := Replicate(initial, []AppendRequest{badMatching, badMismatch, legal})
	if err != nil {
		t.Fatal(err)
	}
	plainJSON, err := json.Marshal(plain)
	if err != nil {
		t.Fatal(err)
	}
	body := string(plainJSON)
	for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
		if strings.Contains(body, field) {
			t.Fatalf("applyKV disabled: output must not contain %q: %s", field, body)
		}
	}
	if strings.Count(body, ReasonEntryTermDecreases) != 2 {
		t.Fatalf("expected exactly two field-error reasons in %s", body)
	}
	if strings.Contains(body, "conflict") {
		t.Fatalf("field-error rejections must omit conflict: %s", body)
	}
}

// uncommittedSuffixInitial 是两个替换规则回归测试共享的初始状态：任期 4，
// 日志索引 1..4 的任期依次为 1、2、4、4；只有 idx1（set balance=100）已提交，
// 后三条（set balance=200、delete balance、set legacy=old）是未提交旧后缀。
func uncommittedSuffixInitial() InitialState {
	return InitialState{CurrentTerm: 4, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 1, "set balance=100"),
		entry(2, 2, "set balance=200"),
		entry(3, 4, "delete balance"),
		entry(4, 4, "set legacy=old"),
	}}
}

// TestKVTermConflictReplacesUncommittedSuffix 回归保障：新条目在 idx2 处与旧
// 日志任期冲突（旧任期 2、新任期 3）后，idx2 及其后的未提交旧后缀被整段替换；
// 替换区间内的新条目（idx3 任期 4）即使与旧位置同任期、命令不同，也不再逐位
// 比对，复制照常成功。已提交前缀 idx1 完整保留，原 idx4 被删除，最终日志只剩
// 三条。开启 applyKV 时提交与应用位置都推进到 3：键值表只反映新日志的命令
// （balance=300、receipt=ok），旧后缀中的 delete balance 与 set legacy=old
// 不得留下任何效果，也没有应用错误。
func TestKVTermConflictReplacesUncommittedSuffix(t *testing.T) {
	out := runKV(t, uncommittedSuffixInitial(),
		AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
			Entries: []LogEntry{
				entry(2, 3, "set balance=300"),
				entry(3, 4, "set receipt=ok"), // 与旧 idx3 同任期不同命令：位于被替换后缀内，允许
			}},
	)

	if len(out.Results) != 1 {
		t.Fatalf("got %d results, want 1", len(out.Results))
	}
	result := out.Results[0]
	if !result.Accepted || result.Reason != ReasonOK {
		t.Fatalf("suffix replacement should be accepted: %+v", result)
	}
	if result.Term != 4 || result.CommittedIndex != 3 {
		t.Fatalf("result state = term %d ci %d, want term 4 ci 3", result.Term, result.CommittedIndex)
	}
	if got := appliedIndexOf(t, result); got != 3 {
		t.Fatalf("result appliedIndex = %d, want 3", got)
	}
	if result.ApplyError != nil {
		t.Fatalf("unexpected apply error: %+v", result.ApplyError)
	}

	// 最终日志：已提交前缀保留，idx2/idx3 换成新条目，原 idx4 被删除。
	wantLog := []LogEntry{
		entry(1, 1, "set balance=100"),
		entry(2, 3, "set balance=300"),
		entry(3, 4, "set receipt=ok"),
	}
	if !reflect.DeepEqual(out.FinalLog, wantLog) {
		t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
	}
	if out.FinalTerm != 4 || out.FinalCommittedIndex != 3 {
		t.Fatalf("final state = term %d ci %d, want term 4 ci 3", out.FinalTerm, out.FinalCommittedIndex)
	}
	if *out.FinalAppliedIndex != 3 {
		t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
	}
	// 键值表只含新日志效果：balance=300 覆盖 100，receipt=ok 写入；
	// 旧后缀的 delete balance 与 set legacy=old 不得生效。
	wantKV := map[string]string{"balance": "300", "receipt": "ok"}
	if !reflect.DeepEqual(finalKVOf(t, out), wantKV) {
		t.Fatalf("final kv = %v, want %v (replaced suffix must not be applied)", out.FinalKV, wantKV)
	}
	if out.FinalApplyError != nil {
		t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
	}
}

// TestKVSameTermConflictOnKeptPrefixRejects 回归保障相反情形：同一初始状态下，
// idx2 的新条目仍用任期 2（与旧条目同任期）但命令改为 set balance=300——冲突
// 位于仍需保留的旧日志位置，整段请求必须按同任期命令冲突拒绝。日志保持原有
// 四条，提交与应用位置停在 1，键值表只有 balance=100，无应用错误。
func TestKVSameTermConflictOnKeptPrefixRejects(t *testing.T) {
	initial := uncommittedSuffixInitial()
	out := runKV(t, initial,
		AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
			Entries: []LogEntry{
				entry(2, 2, "set balance=300"), // 与旧 idx2 同任期不同命令：拒绝
				entry(3, 4, "set receipt=ok"),
			}},
	)

	if len(out.Results) != 1 {
		t.Fatalf("got %d results, want 1", len(out.Results))
	}
	result := out.Results[0]
	if result.Accepted || result.Reason != ReasonCommandConflictSameTerm {
		t.Fatalf("expected same-term command conflict rejection, got %+v", result)
	}
	if result.Term != 4 || result.CommittedIndex != 1 {
		t.Fatalf("rejection changed state: term %d ci %d, want term 4 ci 1",
			result.Term, result.CommittedIndex)
	}
	if got := appliedIndexOf(t, result); got != 1 {
		t.Fatalf("result appliedIndex = %d, want 1", got)
	}
	if result.ApplyError != nil {
		t.Fatalf("rejection must not produce an apply error: %+v", result.ApplyError)
	}

	// 整条请求原子拒绝：日志、提交位置、应用位置与键值表全部保持原值。
	if !reflect.DeepEqual(out.FinalLog, initial.Log) {
		t.Fatalf("log changed after rejection: %+v", out.FinalLog)
	}
	if out.FinalTerm != 4 || out.FinalCommittedIndex != 1 {
		t.Fatalf("final state = term %d ci %d, want term 4 ci 1", out.FinalTerm, out.FinalCommittedIndex)
	}
	if *out.FinalAppliedIndex != 1 {
		t.Fatalf("final appliedIndex = %d, want 1", *out.FinalAppliedIndex)
	}
	if !reflect.DeepEqual(finalKVOf(t, out), map[string]string{"balance": "100"}) {
		t.Fatalf("final kv = %v, want only balance=100", out.FinalKV)
	}
	if out.FinalApplyError != nil {
		t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
	}
}

func TestKVRoundTripFailedReuseKeepsPreviousResult(t *testing.T) {
	original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 1, "set x=1"),
	}},
		AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
			Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
	)
	originalJSON, err := json.Marshal(original)
	if err != nil {
		t.Fatal(err)
	}
	badInputs := []string{
		// 错误位于某条请求答复内：应用索引写成字符串。
		`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"appliedIndex":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
		// 最终层：应用索引写成字符串。
		`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalAppliedIndex":"9"}`,
		// 最终层：键值表写成数组。
		`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalKV":["nope"]}`,
	}
	for _, bad := range badInputs {
		var out ReplicateOutput
		if err := json.Unmarshal(originalJSON, &out); err != nil {
			t.Fatal(err)
		}
		if err := json.Unmarshal([]byte(bad), &out); err == nil {
			t.Fatalf("expected decode error for %s", bad)
		}
		reencoded, err := json.Marshal(out)
		if err != nil {
			t.Fatal(err)
		}
		if string(reencoded) != string(originalJSON) {
			t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
				bad, originalJSON, reencoded)
		}
	}
}

// 溢出非法请求不应用任何命令：请求被字段错误拒绝后日志与提交位置不变，
// appliedIndex 停在初始已提交前缀，键值表不含非法请求中的写入。
func TestKVOverflowFieldErrorAppliesNothing(t *testing.T) {
	out := runKV(t, InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 2, "set a=1"),
	}},
		AppendRequest{Term: 9, PrevLogIndex: math.MaxInt, PrevLogTerm: 0,
			Entries: []LogEntry{entry(math.MinInt, 9, "set evil=1")}},
	)
	result := out.Results[0]
	if result.Accepted || !strings.Contains(result.Reason, "not consecutive") {
		t.Fatalf("expected index-gap field error, got %+v", result)
	}
	if got := appliedIndexOf(t, result); got != 1 {
		t.Fatalf("applied index = %d, want 1", got)
	}
	if result.ApplyError != nil {
		t.Fatalf("unexpected apply error: %+v", result.ApplyError)
	}
	kv := finalKVOf(t, out)
	if _, ok := kv["evil"]; ok {
		t.Fatalf("illegal request command was applied: %+v", kv)
	}
	if kv["a"] != "1" {
		t.Fatalf("initial committed entry missing: %+v", kv)
	}
	if out.FinalAppliedIndex == nil || *out.FinalAppliedIndex != 1 {
		t.Fatalf("final applied index = %+v, want 1", out.FinalAppliedIndex)
	}
}

// 非法请求之后的合法提交仍按现有规则应用：第二条追加索引 2 并提交到 2，
// 键值表随提交位置推进到索引 2。
func TestKVCommitAfterOverflowFieldErrorApplies(t *testing.T) {
	out := runKV(t, InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
		entry(1, 2, "set a=1"),
	}},
		AppendRequest{Term: 9, PrevLogIndex: math.MaxInt, PrevLogTerm: 0,
			Entries: []LogEntry{entry(math.MinInt, 9, "set evil=1")}},
		AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 2, LeaderCommit: 2,
			Entries: []LogEntry{entry(2, 3, "set b=2")}},
	)
	if !out.Results[1].Accepted {
		t.Fatalf("valid request rejected: %+v", out.Results[1])
	}
	if got := appliedIndexOf(t, out.Results[0]); got != 1 {
		t.Fatalf("after field error applied index = %d, want 1", got)
	}
	if got := appliedIndexOf(t, out.Results[1]); got != 2 {
		t.Fatalf("after valid commit applied index = %d, want 2", got)
	}
	kv := finalKVOf(t, out)
	want := map[string]string{"a": "1", "b": "2"}
	if !reflect.DeepEqual(kv, want) {
		t.Fatalf("kv = %+v, want %+v", kv, want)
	}
	if out.FinalTerm != 3 || *out.FinalAppliedIndex != 2 {
		t.Fatalf("unexpected final state: term=%d applied=%+v", out.FinalTerm, out.FinalAppliedIndex)
	}
}

// TestKVRoundTripCaseFoldedPerRequestKeys 回归保障：对现有解码已经接受、仅字母
// 大小写不同的应用字段名（如 "ApplyError"、"APPLIEDINDEX"），读回后按字段已
// 出现处理，不依赖值是否为空——单条答复出现任意一个，再次输出必须同时带上
// appliedIndex 与 applyError，且沿用标准字段名；缺索引补 0，无错误补 null；
// 已提供的非零索引与错误中的索引、原因原样保留。
func TestKVRoundTripCaseFoldedPerRequestKeys(t *testing.T) {
	cases := []struct {
		name      string
		extra     string
		wantIndex float64
		wantError any // nil 表示输出必须为 null；否则为期望的错误对象
	}{
		// 任务中的原始问题场景：只有 "ApplyError": null。
		{"only capitalized null apply error", `"ApplyError":null`, 0, nil},
		{"only uppercase apply index zero", `"APPLIEDINDEX":0`, 0, nil},
		{"only uppercase nonzero apply index", `"APPLIEDINDEX":5`, 5, nil},
		{"only mixed-case apply error object",
			`"aPpLyErRoR":{"index":3,"reason":"boom"}`, 0,
			map[string]any{"index": float64(3), "reason": "boom"}},
		{"capitalized index with capitalized error",
			`"AppliedIndex":4,"ApplyError":{"index":6,"reason":"bad"}`, 4,
			map[string]any{"index": float64(6), "reason": "bad"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			data := `{"accepted":true,"reason":"ok","term":2,"committedIndex":1,` + tc.extra + `}`
			var result AppendResult
			if err := json.Unmarshal([]byte(data), &result); err != nil {
				t.Fatal(err)
			}
			reencoded, err := json.Marshal(result)
			if err != nil {
				t.Fatal(err)
			}
			m := decodeMap(t, reencoded)
			// 必须以标准字段名输出，原始大小写名不得残留。
			mustHaveKeys(t, m, "per-request result", "appliedIndex", "applyError")
			if len(m) != 6 {
				t.Fatalf("unexpected keys in re-encoded result: %v", m)
			}
			if m["appliedIndex"] != tc.wantIndex {
				t.Fatalf("appliedIndex = %v, want %v: %v", m["appliedIndex"], tc.wantIndex, m)
			}
			if tc.wantError == nil {
				if m["applyError"] != nil {
					t.Fatalf("applyError = %v, want null: %v", m["applyError"], m)
				}
			} else if !reflect.DeepEqual(m["applyError"], tc.wantError) {
				t.Fatalf("applyError = %v, want %v", m["applyError"], tc.wantError)
			}
			// 复制答复的既有字段不被大小写变体干扰。
			if m["accepted"] != true || m["reason"] != "ok" ||
				m["term"] != float64(2) || m["committedIndex"] != float64(1) {
				t.Fatalf("replication fields changed: %v", m)
			}
		})
	}
}

// TestKVRoundTripCaseFoldedFinalKeys 最终结果一层的大小写变体约定：
// finalAppliedIndex、finalKV、finalApplyError 中任意一个以任意大小写形式出现，
// 再次输出都必须以标准名带齐三个字段；缺索引补 0、缺或 null 的键值表补 {}、
// 无错误补 null；非零索引、键值内容、错误索引与原因原样保留。
func TestKVRoundTripCaseFoldedFinalKeys(t *testing.T) {
	cases := []struct {
		name      string
		extra     string
		wantIndex float64
		wantKV    any // 期望的键值表（空表为 map[string]any{}）
		wantError any // nil 表示必须输出 null
	}{
		{"only uppercase final applied index zero", `"FINALAPPLIEDINDEX":0`, 0, map[string]any{}, nil},
		{"only capitalized nonzero final applied index", `"FinalAppliedIndex":7`, 7, map[string]any{}, nil},
		{"only uppercase empty final kv", `"FINALKV":{}`, 0, map[string]any{}, nil},
		{"only capitalized null final kv", `"FinalKV":null`, 0, map[string]any{}, nil},
		{"only mixed-case nonempty final kv",
			`"fInAlKv":{"a":"1","b":"x=y"}`, 0,
			map[string]any{"a": "1", "b": "x=y"}, nil},
		{"only capitalized null final apply error", `"FinalApplyError":null`, 0, map[string]any{}, nil},
		{"only uppercase final apply error object",
			`"FINALAPPLYERROR":{"index":2,"reason":"` + ApplyReasonSetMissingEquals + `"}`, 0,
			map[string]any{},
			map[string]any{"index": float64(2), "reason": ApplyReasonSetMissingEquals}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			data := `{"results":[],"finalTerm":2,"finalCommittedIndex":1,` +
				`"finalLog":[{"index":1,"term":1,"command":"set a=1"}],` + tc.extra + `}`
			var out ReplicateOutput
			if err := json.Unmarshal([]byte(data), &out); err != nil {
				t.Fatal(err)
			}
			reencoded, err := json.Marshal(out)
			if err != nil {
				t.Fatal(err)
			}
			m := decodeMap(t, reencoded)
			// 三个标准字段名必须带齐，原始大小写名不得残留。
			mustHaveKeys(t, m, "final output",
				"finalAppliedIndex", "finalKV", "finalApplyError")
			for _, variant := range []string{
				"FINALAPPLIEDINDEX", "FinalAppliedIndex", "fInAlKv",
				"FINALKV", "FinalKV", "FINALAPPLYERROR", "FinalApplyError",
			} {
				if _, ok := m[variant]; ok {
					t.Fatalf("case-variant key %q leaked into output: %v", variant, m)
				}
			}
			if m["finalAppliedIndex"] != tc.wantIndex {
				t.Fatalf("finalAppliedIndex = %v, want %v: %v",
					m["finalAppliedIndex"], tc.wantIndex, m)
			}
			if !reflect.DeepEqual(m["finalKV"], tc.wantKV) {
				t.Fatalf("finalKV = %v, want %v", m["finalKV"], tc.wantKV)
			}
			if tc.wantError == nil {
				if m["finalApplyError"] != nil {
					t.Fatalf("finalApplyError = %v, want null: %v", m["finalApplyError"], m)
				}
			} else if !reflect.DeepEqual(m["finalApplyError"], tc.wantError) {
				t.Fatalf("finalApplyError = %v, want %v", m["finalApplyError"], tc.wantError)
			}
			// 任期、提交位置与日志内容保持原样。
			if m["finalTerm"] != float64(2) || m["finalCommittedIndex"] != float64(1) {
				t.Fatalf("final replication fields changed: %v", m)
			}
		})
	}
}

// TestKVRoundTripCaseFoldedKeysLevelIndependent 大小写变体同样遵守两层各自判断：
// 某条答复以变体名记录应用状态，不能让其他答复或最终结果凭空增加应用字段；
// 最终结果以变体名记录时，反过来也一样。
func TestKVRoundTripCaseFoldedKeysLevelIndependent(t *testing.T) {
	perRequestKeys := []string{"appliedIndex", "applyError"}
	finalKeys := []string{"finalAppliedIndex", "finalKV", "finalApplyError"}

	// 情形一：最终层以变体名记录；请求 0 无应用字段，请求 1 以变体名记录。
	data1 := `{"results":[` +
		`{"accepted":true,"reason":"ok","term":3,"committedIndex":0},` +
		`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"APPLIEDINDEX":2,"ApplyError":{"index":3,"reason":"boom"}}` +
		`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
		`"FINALAPPLIEDINDEX":2,"FinalKV":{"k":"v"},"FINALAPPLYERROR":{"index":3,"reason":"boom"}}`
	var out1 ReplicateOutput
	if err := json.Unmarshal([]byte(data1), &out1); err != nil {
		t.Fatal(err)
	}
	reencoded1, err := json.Marshal(out1)
	if err != nil {
		t.Fatal(err)
	}
	m1 := decodeMap(t, reencoded1)
	results1 := resultMaps(t, m1)
	mustLackKeys(t, results1[0], "plain request", perRequestKeys...)
	mustHaveKeys(t, results1[1], "applied request", perRequestKeys...)
	if results1[1]["appliedIndex"] != float64(2) ||
		!reflect.DeepEqual(results1[1]["applyError"],
			map[string]any{"index": float64(3), "reason": "boom"}) {
		t.Fatalf("applied request values changed: %v", results1[1])
	}
	mustHaveKeys(t, m1, "final output", finalKeys...)
	if !reflect.DeepEqual(m1["finalKV"], map[string]any{"k": "v"}) {
		t.Fatalf("finalKV changed: %v", m1["finalKV"])
	}

	// 情形二：只有请求 0 以变体名记录；最终层与请求 1 必须保持无应用字段。
	data2 := `{"results":[` +
		`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"AppliedIndex":0,"APPLYERROR":null},` +
		`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
		`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`
	var out2 ReplicateOutput
	if err := json.Unmarshal([]byte(data2), &out2); err != nil {
		t.Fatal(err)
	}
	reencoded2, err := json.Marshal(out2)
	if err != nil {
		t.Fatal(err)
	}
	m2 := decodeMap(t, reencoded2)
	results2 := resultMaps(t, m2)
	mustHaveKeys(t, results2[0], "applied request", perRequestKeys...)
	if results2[0]["appliedIndex"] != float64(0) || results2[0]["applyError"] != nil {
		t.Fatalf("applied request values changed: %v", results2[0])
	}
	mustLackKeys(t, results2[1], "plain request", perRequestKeys...)
	mustLackKeys(t, m2, "final output", finalKeys...)
}

// TestKVRoundTripSimilarKeysDoNotTrigger 与应用字段名相似但大小写折叠后仍不
// 相同的无关键，不能触发应用字段补齐；输出形状与完全没有应用字段的旧结果一致。
func TestKVRoundTripSimilarKeysDoNotTrigger(t *testing.T) {
	perRequestSimilar := []string{
		`"myAppliedIndex":9`,
		`"appliedIndex2":9`,
		`"applied_index":9`,
		`"ApplyErrors":null`,
		`"xapplyError":null`,
	}
	for _, extra := range perRequestSimilar {
		data := `{"accepted":true,"reason":"ok","term":1,"committedIndex":0,` + extra + `}`
		var result AppendResult
		if err := json.Unmarshal([]byte(data), &result); err != nil {
			t.Fatalf("decode %s: %v", data, err)
		}
		reencoded, err := json.Marshal(result)
		if err != nil {
			t.Fatal(err)
		}
		m := decodeMap(t, reencoded)
		mustLackKeys(t, m, "result with "+extra, "appliedIndex", "applyError")
		if result.applyFields {
			t.Fatalf("similar key %q must not open apply fields switch", extra)
		}
	}

	finalSimilar := []string{
		`"finalAppliedIndexV2":9`,
		`"finalKVVersion":{}`,
		`"finalApplyErrorCode":null`,
		`"FinalAppliedIndex2":1`,
		`"FINAL_KV":{}`,
	}
	for _, extra := range finalSimilar {
		data := `{"results":[],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[],` + extra + `}`
		var out ReplicateOutput
		if err := json.Unmarshal([]byte(data), &out); err != nil {
			t.Fatalf("decode %s: %v", data, err)
		}
		reencoded, err := json.Marshal(out)
		if err != nil {
			t.Fatal(err)
		}
		m := decodeMap(t, reencoded)
		mustLackKeys(t, m, "output with "+extra,
			"finalAppliedIndex", "finalKV", "finalApplyError")
		if out.applyFields {
			t.Fatalf("similar key %q must not open apply fields switch", extra)
		}
	}
}

