276		}
277		wantLog := []LogEntry{
278			entry(1, 1, "incr count=10"),
279			entry(2, 2, "incr count=-3"),
280		}
281		if !reflect.DeepEqual(out.FinalLog, wantLog) {
282			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
283		}
284		encoded, err := json.Marshal(out)
285		if err != nil {
286			t.Fatal(err)
287		}
288		body := string(encoded)
289		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
290			if strings.Contains(body, field) {
291				t.Fatalf("applyKV disabled: output must not contain %q: %s", field, body)
292			}
293		}
294		if !strings.Contains(body, "incr count=-3") {
295			t.Fatalf("incr command must stay in the log verbatim: %s", body)
296		}
297	}
